class Solution {
  public int[] pourWater(int[] heights, int volume, int k) {
    for (int drop = 0; drop < volume; drop++) {
      int pos = k;
      // move left while not rising, remembering the lowest point reached
      for (int i = k - 1; i >= 0 && heights[i] <= heights[i + 1]; i--) if (heights[i] < heights[pos]) pos = i;
      if (pos == k)
        for (int i = k + 1; i < heights.length && heights[i] <= heights[i - 1]; i++) if (heights[i] < heights[pos]) pos = i;
      heights[pos]++;
    }
    return heights;
  }
}
